return ['domain'=>'zinn-backups','plural-forms'=>'nplurals=2; plural=(n != 1 && n != 2 && n != 3 && (n%10 == 4 || n%10 == 6 || n%10 == 9));','language'=>'tl','project-id-version'=>'zinn-backups','pot-creation-date'=>'2026-10-08T09:17:23+00:00','po-revision-date'=>'2026-10-08T09:17:23+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Backups'=>'Zinn® Backups','https://zinndigital.com/wordpress-plugins/zinn-backups'=>'https://zinndigital.com/wordpress-plugins/zinn-backups','Backs up your WordPress files and database to your own storage — Dropbox, Google Drive, Cloudflare R2, Amazon S3 or any S3-compatible bucket — restores them in one go, and imports backups made by other backup and migration plugins.'=>'Nagba-back up ng iyong mga file at database ng WordPress sa sarili mong storage — Dropbox, Google Drive, Cloudflare R2, Amazon S3 o anumang bucket na tugma sa S3 — ibinabalik ang mga ito sa isang iglap, at nag-i-import ng mga backup na ginawa ng iba pang backup at migration plugin.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Backups'=>'Mga Backup','Get Pro: schedules, several storages, encryption'=>'Kumuha ng Pro: mga iskedyul, ilang imbakan, pag-encrypt','Working…'=>'Gumagana…','Finished'=>'Tapos na','Failed'=>'Nabigo','Cancelled'=>'Kinansela','Cancel'=>'Kanselahin','Restore'=>'Ibalik','Delete'=>'Burahin','Delete this backup from your storage? This cannot be undone.'=>'Burahin ang backup na ito mula sa iyong storage? Hindi na ito mababawi.','No backups yet. Press “Back up now” to make the first one.'=>'Wala pang mga backup. Pindutin ang "I-back up ngayon" para gawin ang una.','Reading your storage…'=>'Binabasa ang iyong storage…','a complete backup, as opposed to an incremental oneFull backup'=>'Kumpletong backup','a backup holding only what changed since an earlier oneIncremental backup'=>'Incremental backup','Encrypted'=>'Naka-encrypt','From another site'=>'Mula sa ibang site','Database'=>'Database','Files'=>'Mga File','Uploading %1$s: %2$s%%'=>'Ina-upload ang %1$s: %2$s%%','Sign in to Dropbox in the window that opened, then paste the code Dropbox shows you:'=>'Mag-sign in sa Dropbox sa window na nagbukas, pagkatapos ay i-paste ang code na ipinapakita sa iyo ng Dropbox:','Saved.'=>'Nai-save na.','Remove this destination from the plugin? The backups stored in it are not deleted.'=>'Alisin ang destinasyong ito mula sa plugin? Hindi tatanggalin ang mga backup na nakaimbak dito.','Reload the page to see the restored site.'=>'I-reload ang pahina upang makita ang naibalik na site.','Storage'=>'Storage','Import & migrate'=>'Mag-import at mag-migrate','Settings'=>'Mga Setting','Sections'=>'Mga Seksiyon','Google Drive is connected.'=>'Nakakonekta ang Google Drive.','Google Drive could not be connected.'=>'Hindi maikonekta ang Google Drive.','Details'=>'Mga Detalye','Back up now'=>'Mag-backup ngayon','Backups go to your own storage, not this server. <a href="%s">Connect your storage</a> first.'=>'Pumupunta ang mga backup sa sarili mong storage, hindi sa server na ito. <a href="%s">Ikonekta muna ang iyong storage</a>.','What to back up'=>'Kung ano ang iba-backup','Files and database'=>'Mga file at database','Database only'=>'Database lamang','Files only'=>'Mga file lamang','Note (optional)'=>'Paalala (opsyonal)','Each part is uploaded to your storage and removed from this server before the next one is made, so the backup never takes up room on your hosting.'=>'Ina-upload ang bawat bahagi sa iyong storage at inaalis mula sa server na ito bago gawin ang susunod, kaya hindi kailanman kumukuha ng espasyo ang backup sa iyong hosting.','Your backups'=>'Ang iyong mga backup','Refresh'=>'I-refresh','Restore this backup'=>'Ibalik ang backup na ito','Passphrase'=>'Passphrase','I understand this replaces this site’s files and database with the backup’s. Files that are not in the backup are kept.'=>'Nauunawaan ko na pinapalitan nito ang mga file at database ng site na ito ng mga nasa backup. Pananatilihin ang mga file na wala sa backup.','Recent activity'=>'Kamakailang aktibidad','Backup'=>'Backup','Restore / import'=>'Ibalik / i-import','Running'=>'Tumatakbo','Your storage'=>'Ang iyong storage' . "\0" . 'Iyong mga destinasyon ng storage','No storage yet. Choose where your backups go below.'=>'Wala pang storage. Piliin sa ibaba kung saan mapupunta ang mga backup mo.','Ready'=>'Handa','Not connected'=>'Hindi nakakonekta','Connect'=>'Ikonekta','Test'=>'Subukan','Edit'=>'I-edit','Remove'=>'Alisin','Add storage'=>'Magdagdag ng storage','Backups go to one storage destination. To use a different one, edit or remove the one above.'=>'Napupunta ang mga backup sa iisang imbakan. Para gumamit ng iba, i-edit o alisin ang nasa itaas.','Kind of storage'=>'Uri ng storage','Name (for you)'=>'Pangalan (para sa iyo)','Provider'=>'Provider','Cloudflare account id'=>'ID ng Cloudflare account','Endpoint address'=>'Address ng endpoint','Region'=>'Rehiyon','Bucket'=>'Bucket','Access key id'=>'ID ng access key','Secret access key'=>'Lihim na access key','Leave empty to keep the saved key'=>'Iwanang blangko upang panatilihin ang naka-save na key','For Cloudflare R2: in the Cloudflare dashboard open R2, create a bucket, then “Manage R2 API tokens” → create a token with Object Read & Write for that bucket, and copy the access key id and secret here.'=>'Para sa Cloudflare R2: sa Cloudflare dashboard, buksan ang R2, gumawa ng bucket, pagkatapos ay “Manage R2 API tokens” → gumawa ng token na may Object Read & Write para sa bucket na iyon, at kopyahin ang access key id at secret dito.','Dropbox app key'=>'Key ng Dropbox app','Create an app at dropbox.com/developers/apps (Scoped access, App folder) with the files.content.read, files.content.write and files.metadata.read permissions, and copy its App key here. Save, then press Connect.'=>'Gumawa ng app sa dropbox.com/developers/apps (Scoped access, App folder) na may mga pahintulot na files.content.read, files.content.write, at files.metadata.read, at kopyahin ang App key nito rito. I-save, pagkatapos ay pindutin ang Connect.','OAuth client id'=>'OAuth client ID','OAuth client secret'=>'Lihim ng client ng OAuth','Leave empty to keep the saved secret'=>'Iwanang blangko upang panatilihin ang naka-save na lihim','In Google Cloud Console, enable the Google Drive API, then create an OAuth client of type “Web application” with this address as an authorised redirect URI:'=>'Sa Google Cloud Console, i-enable ang Google Drive API, pagkatapos ay gumawa ng OAuth client na may uri na "Web application" gamit ang address na ito bilang awtorisadong redirect URI:','Save, then press Connect. The plugin only sees the files it creates.'=>'I-save, pagkatapos ay pindutin ang Ikonekta. Nakikita lang ng plugin ang mga file na nililikha nito.','Folder inside the storage (optional)'=>'Folder sa loob ng storage (opsyonal)','Save storage'=>'Magtipid ng storage','Import a backup from another plugin or host'=>'Mag-import ng backup mula sa ibang plugin o host','Bring a site in from a backup made by UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate, or any zip/tar archive of a WordPress site with its .sql dump. The content goes into wp-content and the database replaces this site’s; addresses are changed to this site’s automatically.'=>'Mag-import ng site mula sa isang backup na ginawa ng UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate, o anumang zip/tar archive ng isang WordPress site kasama ang .sql dump nito. Mapupunta ang nilalaman sa wp-content at papalitan ng database ang sa site na ito; awtomatikong papalitan ang mga address upang itugma sa site na ito.','Upload from your computer'=>'Mag-upload mula sa iyong computer','Choose every file of the backup at once (UpdraftPlus makes several). Large files are sent in small pieces, so your host’s upload limit does not apply.'=>'Piliin ang bawat file ng backup nang sabay-sabay (gumagawa ang UpdraftPlus ng ilan). Ipinapadala ang malalaking file sa maliliit na piraso, kaya hindi nalalapat ang limitasyon sa pag-upload ng iyong host.','Or from links (Google Drive, Dropbox or any download address)'=>'O mula sa mga link (Google Drive, Dropbox, o anumang download address)','One link per line. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link; turn sharing off again afterwards.'=>'Isang link bawat linya. Para sa Google Drive at Dropbox, ibahagi ang file sa "sinumang may link" at i-paste ang link na iyon; i-off muli ang pagbabahagi pagkatapos.','Or a file already on this server'=>'O isang file na nasa server na ito','Upload archives by FTP or your host’s file manager into %s and reload this page.'=>'Mag-upload ng mga archive sa pamamagitan ng FTP o file manager ng iyong host sa %s at i-reload ang pahinang ito.','Or a deploy code from another site'=>'O isang deploy code mula sa ibang site','If another site gave you a Zinn® Backups deploy code, paste it here to copy that backup onto this site without sharing its storage keys. A code works for a few hours; treat it like a password.'=>'Kung binigyan ka ng isa pang site ng Zinn® Backups deploy code, i-paste ito rito upang kopyahin ang backup na iyon sa site na ito nang hindi ibinabahagi ang mga storage key nito. Gumagana ang code sa loob ng ilang oras; ituring ito tulad ng isang password.','Passphrase (only if that backup is encrypted)'=>'Passphrase (kung naka-encrypt lang ang backup na iyon)','Import'=>'Mag-import','I understand the import replaces this site’s content and database. After it, sign in with an account from the imported site.'=>'Naiintindihan ko na papalitan ng pag-import ang nilalaman at database ng site na ito. Pagkatapos nito, mag-sign in gamit ang isang account mula sa na-import na site.','Moving to Zinn® hosting?'=>'Lumilipat sa hosting ng Zinn®?','Zinn Digital® can move your site for you from your old host. If your old host gives you no FTP, SSH or control-panel access, install Zinn® Migrate on the old site; it makes one archive you can import here or hand to Zinn®.'=>'Maaaring ilipat ng Zinn Digital® ang iyong site mula sa iyong lumang host para sa iyo. Kung ang iyong lumang host ay hindi nagbibigay sa iyo ng access sa FTP, SSH o control-panel, i-install ang Zinn® Migrate sa lumang site; gumagawa ito ng isang archive na maaari mong i-import dito o ibigay sa Zinn®.','What goes into a backup'=>'Kung ano ang kasama sa isang backup','Include WordPress’s own files (wp-admin, wp-includes). Usually not needed: WordPress can always be reinstalled.'=>'Isama ang sariling mga file ng WordPress (wp-admin, wp-includes). Karaniwang hindi kinakailangan: laging maaaring muling i-install ang WordPress.','Also leave out these folders or files (one per line, relative to the WordPress folder)'=>'Iwanan din ang mga folder o file na ito (isa bawat linya, may kaugnayan sa WordPress folder)','Always left out: caches, update scratch space, and other backup plugins’ own archive folders:'=>'Palaging hindi kasama: mga cache, espasyo para sa update scratch, at sariling mga archive folder ng iba pang backup plugin:','Size of each part (MB)'=>'Laki ng bawat bahagi (MB)','Save settings'=>'I-save ang mga setting','A backup part could not be opened for writing. Check that wp-content has free space.'=>'Hindi mabuksan para sa pagsulat ang isang bahagi ng backup. Suriin kung may bakanteng espasyo ang wp-content.','A backup part could not be written. Check that wp-content has free space.'=>'Hindi maisulat ang isang bahagi ng backup. Suriin kung may bakanteng espasyo ang wp-content.','Connect a storage destination on the Storage tab first: backups are kept in your own storage, not on this server.'=>'Magkonekta muna ng storage destination sa tab na Storage: ang mga backup ay itinatago sa sarili mong storage, hindi sa server na ito.','Multisite networks are not supported yet.'=>'Hindi pa suportado ang mga multisite network.','This server’s PHP has no ZipArchive extension. Ask your host to enable it.'=>'Walang ZipArchive extension ang PHP ng server na ito. Hilingin sa iyong host na i-enable ito.','Starting'=>'Sinisimulan','Listing files'=>'Inililista ang mga file','Backing up the database'=>'Ibinaback up ang database','Packing files'=>'Ipinapakete ang mga file','Uploading to your storage'=>'Nag-a-upload sa iyong storage','Finishing'=>'Tinatapos','The backup reached an unknown stage.'=>'Naabot ng backup ang isang hindi kilalang yugto.','Backup %s started.'=>'Nagsimula na ang backup ng %s.','Found %1$s files (%2$s).'=>'Nahanap ang %1$s na (mga) file (%2$s).','Database: %1$d tables, %2$s rows, %3$s compressed.'=>'Database: %1$d mga talahanayan, %2$s mga hilera, %3$s naka-compress.','Backup complete: %1$s stored in %2$d destination.'=>'Kumpleto na ang backup: naimbak ang %1$s sa %2$d patutunguhan.' . "\0" . 'Kumpleto na ang backup: Na-store ang %1$s sa %2$d (na) destinasyon.','Some parts already uploaded could not be removed from your storage; they are in an incomplete backup folder and are never offered for restore.'=>'Ang ilang bahaging na-upload na ay hindi maalis sa iyong storage; ang mga ito ay nasa isang folder ng hindi kumpletong backup at hindi kailanman iniaalok para sa pag-restore.','A storage destination was removed while the backup was running.'=>'Inalis ang isang imbakan habang tumatakbo ang backup.','That is not a backup folder.'=>'Hindi iyon backup folder.','That storage destination is no longer saved on this site.'=>'Hindi na naka-save sa site na ito ang destinasyon ng imbakan na iyon.','Later incremental backups are built on this one. Delete those first.'=>'Ang mga susunod na incremental backup ay nakabatay dito. Burahin muna ang mga iyon.','This file is not an encrypted Zinn® Backups file.'=>'Ang file na ito ay hindi isang naka-encrypt na Zinn® Backups file.','The backup could not be decrypted: the passphrase is wrong or the file is damaged.'=>'Hindi ma-decrypt ang backup: mali ang passphrase o sira ang file.','The encrypted backup file is incomplete.'=>'Hindi kumpleto ang naka-encrypt na backup file.','The database file could not be written. Check that wp-content has free space.'=>'Hindi maisulat ang database file. Suriin kung may libreng espasyo ang wp-content.','That is not a deploy code. A deploy code starts with zbdeploy1.'=>'Hindi iyan deploy code. Ang deploy code ay nagsisimula sa zbdeploy1.','That deploy code is damaged. Copy it again from the other site.'=>'Sira ang deploy code na iyon. Kopyahin mo itong muli mula sa kabilang site.','The deploy code has expired or its backup was deleted. Make a new code on the other site.'=>'Nag-expire na ang deploy code o nabura ang backup nito. Gumawa ng bagong code sa kabilang site.','That deploy code does not point at a Zinn® Backups backup.'=>'Ang deploy code na iyon ay hindi tumuturo sa isang backup ng Zinn® Backups.','The deploy code has expired. Make a new code on the other site.'=>'Nag-expire na ang deploy code. Gumawa ng bagong code sa kabilang site.','The server stopped honouring partial downloads. Start the import again.'=>'Itinigil ng server ang pagtanggap sa mga bahagyang pag-download. Simulan muli ang pag-import.','The link opened a web page instead of a file. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link.'=>'Nagbukas ang link ng isang webpage sa halip na file. Para sa Google Drive at Dropbox, ibahagi ang file sa "sinumang may link" at i-paste ang link na iyon.','The link answered with HTTP %d.'=>'Sumagot ang link gamit ang HTTP %d.','The file list could not be written.'=>'Hindi maisulat ang listahan ng file.','The storage service could not be reached: %s'=>'Hindi maabot ang serbisyo ng storage: %s','%1$s answered with HTTP %2$d: %3$s'=>'Sumagot ang %1$s nang may HTTP %2$d: %3$s','no details given'=>'Walang ibinigay na detalye','You are not allowed to manage backups.'=>'Wala kang pahintulot na mamahala ng mga backup.','Tick the box to confirm that the restore replaces this site’s files and database.'=>'Lagyan ng tsek ang kahon upang kumpirmahing papalitan ng pag-restore ang mga file at database ng site na ito.','Save the destination first.'=>'I-save muna ang destinasyon.','Connected: a test file was written and removed.'=>'Konektado: naisulat at naalis ang isang pansubok na file.','Enter the app key of your Dropbox app first (see the steps beside the form).'=>'Ilagay muna ang app key ng iyong Dropbox app (tingnan ang mga hakbang sa tabi ng form).','This kind of storage does not sign in.'=>'Ang ganitong uri ng storage ay hindi nag-sa-sign in.','The sign-in expired. Press Connect again.'=>'Nag-expire ang pag-sign in. Pindutin muli ang Ikonekta.','Dropbox is connected.'=>'Konektado ang Dropbox.','Settings saved.'=>'Nai-save ang mga setting.','Another backup, restore or import is running. Wait for it to finish, or cancel it.'=>'May isa pang backup, restore, o import na kasalukuyang tumatakbo. Maghintay hanggang sa matapos ito, o kanselahin ito.','The upload was not started properly. Start again.'=>'Hindi nagsimula nang maayos ang pag-upload. Magsimula muli.','The chunk did not arrive. Your server may limit upload sizes; try again.'=>'Hindi nakarating ang piraso. Maaaring nililimitahan ng iyong server ang laki ng pag-upload; subukang muli.','Tick the box to confirm that the import replaces this site’s content and database.'=>'Lagyan ng tsek ang kahon upang kumpirmahing papalitan ng pag-import ang nilalaman at database ng site na ito.','Choose an archive to import: upload it, paste a link, or pick one from the import folder.'=>'Pumili ng archive na ii-import: i-upload ito, mag-paste ng link, o pumili mula sa folder ng pag-import.','Hosting customer? Get %1$d%% off %2$s'=>'Customer ng hosting? Kumuha ng %1$d%% diskwento sa %2$s','As a Zinn Digital® hosting customer you get a personal code for %d%% off your first payment. Renewals are at the normal price.'=>'Bilang customer ng hosting ng Zinn Digital®, makakakuha ka ng personal na code para sa %d%% diskwento sa iyong unang bayad. Ang mga pag-renew ay nasa normal na presyo.','Get my %d%% code and go to checkout'=>'Kunin ang aking %d%% code at pumunta sa checkout','Sorry, you are not allowed to do that.'=>'Paumanhin, wala kang pahintulot na gawin iyan.','This discount is for customers with a paid hosting plan in good standing. Free trials do not qualify.'=>'Ang diskwentong ito ay para sa mga customer na may binabayarang hosting plan na may magandang katayuan. Hindi kwalipikado ang mga libreng trial.','You have already used your hosting-customer discount for this plugin.'=>'Nagamit mo na ang iyong diskwento bilang customer ng hosting para sa plugin na ito.','We could not get your code just now. Please try again in a few minutes.'=>'Hindi namin makuha ang iyong code ngayon lang. Pakisubukan muli pagkaraan ng ilang minuto.','Reading the backup'=>'Binabasa ang backup','Downloading the archive'=>'Dina-download ang archive','Recognising the archive'=>'Kinikilala ang archive','Restoring files'=>'Ibinabalik ang mga file','Downloading the database'=>'Dina-download ang database','Restoring the database'=>'Ipinapanumbalik ang database','Updating the site address'=>'Ina-update ang address ng site','Switching to the restored database'=>'Lumilipat sa na-restore na database','The restore reached an unknown stage.'=>'Naabot ng pagpapanumbalik ang isang hindi kilalang yugto.','This folder has no complete Zinn® Backups backup in it (the manifest is missing).'=>'Walang kumpletong backup ng Zinn® Backups ang folder na ito (nawawala ang manifest).','This backup is encrypted. Enter its passphrase to restore it.'=>'Naka-encrypt ang backup na ito. Ilagay ang passphrase nito para i-restore ito.','This incremental backup needs backup %s, which is no longer in the storage.'=>'Kailangan ng incremental backup na ito ang backup na %s, na wala na sa storage.','Restoring the backup of %1$s (%2$d file parts).'=>'Ibinabalik ang backup ng %1$s (%2$d bahagi ng file).','%1$s file could not be overwritten because this site is not allowed to change it, and was left as it is: %2$s'=>'Hindi mapalitan ang %1$s file dahil walang pahintulot ang site na ito na baguhin ito, at iniwan ito tulad ng dati: %2$s' . "\0" . 'Hindi ma-overwrite ang %1$s mga file dahil hindi pinapayagan ang site na ito na baguhin ang mga ito, at iniwan ang mga ito kung ano sila: %2$s','Restored %s files.'=>'Naibalik ang %s (na) file.','%s did not match its checksum after downloading. The copy in storage may be damaged.'=>'Hindi tumugma ang %s sa checksum nito pagkatapos ma-download. Maaaring sirâ ang kopya sa storage.','%s did not arrive. Upload it again.'=>'Hindi dumating ang %s. I-upload itong muli.','Recognised: %s.'=>'Kinikilala: %s.','Imported %1$s files into wp-content (%2$s left out: caches, drop-ins and other backup plugins’ folders).'=>'Na-import ang %1$s mga file sa wp-content (%2$s ang iniwan: mga cache, mga drop-in at mga folder ng iba pang backup plugin).','The archive has no database dump, so only files were imported.'=>'Walang database dump ang archive, kaya mga file lang ang na-import.','Database restored into %d temporary tables.'=>'Na-restore ang database sa %d pansamantalang (mga) talahanayan.','%s has no WordPress tables in it and was skipped.'=>'Walang mga talahanayan ng WordPress ang %s at nilaktawan ito.','The backup’s database has no WordPress tables, so nothing was replaced.'=>'Walang mga WordPress table ang database ng backup, kaya walang pinalitan.','This backup is of a multisite network. Restoring a network into a single site is not supported.'=>'Ang backup na ito ay mula sa isang multisite network. Hindi sinusuportahan ang pag-restore ng network sa isang site lang.','Moving the content from %1$s to %2$s.'=>'Inililipat ang nilalaman mula %1$s patungong %2$s.','Restore complete. If you are signed out, sign in with an account from the restored site.'=>'Tapos na ang pag-restore. Kung naka-sign out ka, mag-sign in gamit ang isang account mula sa na-restore na site.','Restore complete.'=>'Kumpleto na ang pag-restore.','%1$s — trying again in %2$d seconds.'=>'%1$s — sinusubukang muli sa loob ng %2$d segundo.','Cancelled.'=>'Kinansela.','Backups go to one storage destination. Edit or remove the one you have to use a different one.'=>'Pumupunta ang mga backup sa isang destinasyon ng imbakan. I-edit o alisin ang mayroon ka upang gumamit ng iba.','The database file could not be opened.'=>'Hindi mabuksan ang database file.','The database refused a statement from the backup: %1$s (%2$s…)'=>'Tinanggihan ng database ang isang pahayag mula sa backup: %1$s (%2$s…)','The restored tables could not be swapped in: %s. Your site is unchanged.'=>'Hindi mapalitan ang mga naibalik na table: %s. Walang pagbabago sa iyong site.','There is no writable folder for temporary backup files. Make wp-content writable and try again.'=>'Walang masusulatang folder para sa mga pansamantalang backup file. Gawing writable ang wp-content at subukan muli.','Could not create a folder for this job.'=>'Hindi makagawa ng folder para sa gawaing ito.','%s — guides and services'=>'%s — mga gabay at serbisyo','User guides'=>'Mga gabay para sa gumagamit','Read the %s user guide'=>'Basahin ang gabay ng gumagamit ng %s','Hide this'=>'Itago ito','Zinn® hosting for WordPress'=>'Zinn® hosting para sa WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, pang-araw-araw na backup, libreng migrasyon, at control panel na binuo para sa mga taong nagpapatakbo ng higit sa isang site.','The Zinn® marketplace'=>'Ang marketplace ng Zinn®','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Bumili at magbenta ng mga naitatag nang site, domain, at paglalagay ng link, kung saan ligtas na hawak ang pera hanggang sa maging masaya ang magkabilang panig.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — kumuha ng mga taong ito ang ikinabubuhay','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Ang aming pambuong-daigdigang freelance marketplace: mag-browse ng mahigit 10,000 handang serbisyo mula sa mga manunulat, designer, developer, at SEO, o mag-post ng proyekto at hayaan silang mag-bid.','See the Zinn Digital® release notes.'=>'Tingnan ang mga tala sa paglabas ng Zinn Digital®.','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'Hindi nagbigay ang serbisyo sa pag-update ng Zinn® ng link sa pag-download para sa update na ito. Suriin kung maaabot ng site na ito ang Zinn® platform, pagkatapos ay subukan muli.','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'Hindi ma-download ang update mula sa serbisyo ng pag-update ng Zinn® (%s). Subukan muli pagkalipas ng ilang minuto.','The downloaded update failed its integrity check and was not installed.'=>'Bumagsak sa pagsusuri ng integridad ang na-download na update at hindi na-install.','The zip archive could not be opened. It may be damaged or incomplete.'=>'Hindi mabuksan ang zip archive. Maaaring sira o hindi kumpleto ito.','This .wpress file uses a format we cannot read (it may be compressed or encrypted by All-in-One WP Migration). Export it again without encryption.'=>'Gumagamit ang .wpress file na ito ng format na hindi namin mabasa (maaaring na-compress o na-encrypt ito ng All-in-One WP Migration). I-export itong muli nang walang encryption.','This is a Duplicator “DupArchive” (.daf) file. In Duplicator, build the package again with the archive format set to ZIP, then import that.'=>'Isa itong Duplicator “DupArchive” (.daf) na file. Sa Duplicator, buuin muli ang package na ang archive format ay nakatakda sa ZIP, pagkatapos ay i-import iyon.','This UpdraftPlus database backup is encrypted. Decrypt it in UpdraftPlus (or turn off database encryption and back up again), then import it.'=>'Naka-encrypt ang UpdraftPlus database backup na ito. I-decrypt ito sa UpdraftPlus (o i-off ang database encryption at mag-backup muli), pagkatapos ay i-import ito.','Database dump'=>'Dump ng database','%s is not a backup archive we can read (zip, tar, tar.gz, .wpress, .sql or .sql.gz).'=>'Ang %s ay hindi isang backup archive na mababasa natin (zip, tar, tar.gz, .wpress, .sql, o .sql.gz).','Website archive'=>'Archive ng website','%s has no WordPress content (no wp-content folder and no database dump) in it.'=>'Walang nilalaman na WordPress ang %s (walang wp-content na folder at walang database dump).','This .wpress file is encrypted or compressed by All-in-One WP Migration. Export it again with encryption and compression switched off, then import that.'=>'Ang .wpress file na ito ay naka-encrypt o naka-compress ng All-in-One WP Migration. I-export ito muli nang naka-off ang pag-encrypt at pag-compress, pagkatapos ay i-import iyon.','Other S3-compatible storage'=>'Iba pang storage na tugma sa S3','Cloudflare R2, Amazon S3 or S3-compatible'=>'Cloudflare R2, Amazon S3 o tugma sa S3','The storage keys could not be read on this site. Enter the secret key again on the Storage tab.'=>'Hindi mabasa ang mga storage key sa site na ito. Ilagay muli ang secret key sa Storage tab.','This kind of storage is not known.'=>'Hindi kilala ang ganitong uri ng storage.','Choose a kind of storage.'=>'Pumili ng uri ng storage.','Enter the bucket name and the access key.'=>'Ilagay ang pangalan ng bucket at ang access key.','Enter your Cloudflare account id (or the full R2 endpoint).'=>'Ilagay ang iyong Cloudflare account ID (o ang buong R2 endpoint).','Enter the endpoint address of your storage.'=>'Ilagay ang endpoint address ng iyong storage.','Enter the OAuth client id from your Google Cloud project.'=>'Ilagay ang OAuth client id mula sa iyong proyekto sa Google Cloud.','Dropbox did not return a refresh token. Start the connection again.'=>'Hindi nagbalik ang Dropbox ng refresh token. Simulan muli ang koneksyon.','Dropbox is not connected. Connect it again on the Storage tab.'=>'Hindi nakakonekta ang Dropbox. Ikonekta itong muli sa tab na Storage.','Google did not return a refresh token. Remove this site from your Google account’s third-party access and connect again.'=>'Hindi nagbalik ang Google ng refresh token. Alisin ang site na ito mula sa third-party access ng iyong Google account at kumonekta muli.','That file is not in Google Drive any more.'=>'Wala na ang file na iyon sa Google Drive.','Google Drive is not connected. Connect it again on the Storage tab.'=>'Hindi nakakonekta ang Google Drive. Ikonekta itong muli sa tab ng Storage.','The storage service did not start the upload.'=>'Hindi sinimulan ng serbisyo ng imbakan ang pag-upload.','The storage service sent a reply that could not be read.'=>'Nagpadala ang serbisyo ng storage ng sagot na hindi mabasa.','A temporary backup file could not be read.'=>'Hindi mabasa ang isang pansamantalang backup file.','A deploy link is read-only.'=>'Ang deploy link ay read-only.','The deploy code has no link for a file this backup needs.'=>'Walang link ang deploy code para sa isang file na kailangan ng backup na ito.','The deploy link'=>'Ang link ng pag-deploy']];